import { Components, Theme } from "@mui/material/styles";

const components: Components<Omit<Theme, "components">> = {
  MuiCssBaseline: {
    styleOverrides: {
      body: {
        backgroundColor: "#F8F9FA",
        color: "#1A1A1A",
        WebkitFontSmoothing: "antialiased",
        MozOsxFontSmoothing: "grayscale",
      },
      "*": {
        boxSizing: "border-box",
      },
      "#root": {
        minHeight: "100vh",
      },
    },
  },

  MuiPaper: {
    styleOverrides: {
      root: {
        borderRadius: 12,
        backgroundImage: "none",
      },
    },
  },

  MuiCard: {
    defaultProps: {
      elevation: 0,
    },
    styleOverrides: {
      root: {
        borderRadius: 12,
        border: "1px solid #E0E0E0",
        boxShadow: "0 2px 8px rgba(0, 0, 0, 0.05)",
        overflow: "hidden",
        transition: "all 0.2s ease",
        "&:hover": {
          boxShadow: "0 4px 16px rgba(0, 0, 0, 0.1)",
          transform: "translateY(-2px)",
        },
      },
    },
  },

  MuiButton: {
    defaultProps: {
      disableElevation: true,
    },
    styleOverrides: {
      root: {
        borderRadius: 8,
        padding: "10px 24px",
        fontWeight: 600,
        minHeight: 40,
        textTransform: "none",
      },

      contained: {
        boxShadow: "none",
        "&:hover": {
          boxShadow: "0 4px 12px rgba(0, 61, 165, 0.3)",
        },
      },

      outlined: {
        borderWidth: 2,
        "&:hover": {
          borderWidth: 2,
        },
      },
    },
  },

  MuiOutlinedInput: {
    styleOverrides: {
      root: {
        borderRadius: 8,
        "& fieldset": {
          borderColor: "#E0E0E0",
        },
        "&:hover fieldset": {
          borderColor: "#003DA5",
        },
        "&.Mui-focused fieldset": {
          borderWidth: 2,
        },
      },
    },
  },

  MuiTableContainer: {
    styleOverrides: {
      root: {
        borderRadius: 12,
        border: "1px solid #E0E0E0",
      },
    },
  },

  MuiTableHead: {
    styleOverrides: {
      root: {
        backgroundColor: "#F5F7FA",
      },
    },
  },

  MuiTableCell: {
    styleOverrides: {
      head: {
        fontWeight: 700,
        color: "#003DA5",
        borderBottom: "2px solid #E0E0E0",
      },
      root: {
        paddingTop: 16,
        paddingBottom: 16,
        borderBottom: "1px solid #F0F0F0",
      },
    },
  },

  MuiChip: {
    styleOverrides: {
      root: {
        borderRadius: 6,
        fontWeight: 600,
      },
    },
  },

  MuiDivider: {
    styleOverrides: {
      root: {
        borderColor: "#E0E0E0",
      },
    },
  },

  MuiTooltip: {
    styleOverrides: {
      tooltip: {
        borderRadius: 8,
        fontSize: "0.8125rem",
        backgroundColor: "#1A1A1A",
      },
    },
  },
};

export default components;
